        check("empty doc", empty.select("div:has(span, p)").size(), 0);
        check("no match", doc.select("div:has(em, table)").size(), 0);

        // 5. cross-document independence
        Document doc2 = Jsoup.parse("<div id=x><em></em></div>");
        check("doc2 independent", ids(doc2.select("div:has(span, em)")), "x");
