import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.QueryParser;
import org.jsoup.select.Selector;
import java.util.*;
import java.util.concurrent.*;

public class Probe6 {
    static int failures = 0;
    static void check(String label, Object actual, Object expected) {
        boolean ok = expected.equals(actual);
        if (!ok) failures++;
        System.out.println((ok ? "PASS " : "FAIL ") + label + " -> " + actual + (ok ? "" : " (expected " + expected + ")"));
    }
    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        els.forEach(e -> sb.append(e.id()).append(','));
        return sb.length() == 0 ? "" : sb.substring(0, sb.length()-1);
    }
    public static void main(String[] args) throws Exception {
        // escaped class names matched by DOM value
        Document esc = Jsoup.parse(
            "<div id=c1><span class=\"foo:bar\"></span></div>" +
            "<div id=c2><span class=\"a b\"></span></div>");
        check("escaped class", ids(esc.select("div:has(.foo\\:bar, .zz)")), "c1");
        check("multi class", ids(esc.select("div:has(span.a.b, em)")), "c2");

        // whitespace around commas
        Document doc = Jsoup.parse("<div id=a><span></span></div><div id=b><p></p></div>");
        check("ws commas", ids(doc.select("div:has( span , p )")), "a,b");
        check("ws commas 2", ids(doc.select("div:has(span,p)")), "a");
        check("newline in has", ids(doc.select("div:has(span,\n p)")), "a,b");

        // multi-level nested :has with commas at both levels
        Document nest = Jsoup.parse(
            "<section id=n1><div><span></span></div></section>" +
            "<section id=n2><div><p></p></div></section>" +
            "<section id=n3><p></p></section>");
        check("nested both levels", ids(nest.select("section:has(div:has(span, em), > p)")), "n1,n3");

        // :has with > and space chains across branches
        Document chain = Jsoup.parse(
            "<div id=h1><p><b></b></p></div>" +
            "<div id=h2><b></b></div>");
        check("chain branches", ids(chain.select("div:has(p b, > b)")), "h1,h2");
        check("chain strict", ids(chain.select("div:has(p > b)")), "h1");

        // concurrent reuse of one evaluator across documents
        Evaluator ev = QueryParser.parse("div:has(span, p)");
        List<Future<String>> futures = new ArrayList<>();
        ExecutorService pool = Executors.newFixedThreadPool(8);
        for (int t = 0; t < 32; t++) {
            final int n = t;
            futures.add(pool.submit(() -> {
                Document d = Jsoup.parse("<div id=d" + n + "><span></span></div><div><em></em></div>");
                return ids(Selector.select(ev, d));
            }));
        }
        boolean concOk = true;
        for (int t = 0; t < 32; t++) {
            if (!futures.get(t).get().equals("d" + t)) concOk = false;
        }
        pool.shutdown();
        check("concurrent reuse", concOk, true);

        // serialized result of selection contains no new nodes
        Document m = Jsoup.parse("<div id=m1><p>x</p></div>");
        String beforeHtml = m.html();
        m.select("div:has(p, span)");
        check("query no mutation", m.html(), beforeHtml);

        // selectFirst / selectNodes paths with commas
        check("selectFirst", m.selectFirst("div:has(p, span)").id(), "m1");
        check("selectFirst none", m.selectFirst("div:has(em, table)"), null);

        System.out.println(failures == 0 ? "ALL PASS" : failures + " FAILURES");
    }
}
